sp_widget.client_script:
api.controller = function($scope) {

    var c = this;

    c.search = '';
    c.loading = false;
    c.sidebarCollapsed = false;
    c.selectedSection = 'dashboard';
    c.showNotificationsPopover = false;
    c.activeNotifTab = 'all';

    c.toggleNotifications = function($event) {
        if ($event) $event.stopPropagation();
        c.showNotificationsPopover = !c.showNotificationsPopover;
    };

    c.dismissNotification = function(notif) {
        if (!notif) return;
        c.server.get({
            action: 'dismiss_notification',
            sys_id: notif.sys_id
        }).then(function(r) {
            c.data.notifications = r.data.notifications;
            c.data.unreadCount = r.data.unreadCount;
        });
    };

    c.ignoreOpportunity = function(notif) {
        if (!notif) return;
        var oppId = notif.opportunity_id;
        c.server.get({
            action: 'ignore_opportunity',
            opp_id: oppId
        }).then(function(r) {
            c.data.notifications = r.data.notifications;
            c.data.unreadCount = r.data.unreadCount;
        });
    };

    c.clearAllNotifications = function() {
        c.server.get({
            action: 'clear_all_notifications'
        }).then(function(r) {
            c.data.notifications = r.data.notifications;
            c.data.unreadCount = r.data.unreadCount;
        });
    };

    c.getFilteredNotifications = function() {
        if (!c.data || !c.data.notifications) return [];
        if (c.activeNotifTab === 'deadlines') {
            return c.data.notifications.filter(function(n) { return n.is_deadline || n.type === 'opportunity_deadline'; });
        }
        if (c.activeNotifTab === 'interviews') {
            return c.data.notifications.filter(function(n) { return n.type === 'interview' || n.type === 'assessment'; });
        }
        if (c.activeNotifTab === 'shortlist') {
            return c.data.notifications.filter(function(n) { return n.type === 'shortlisted'; });
        }
        return c.data.notifications;
    };

    c.refreshDashboard = function() {
        if (c.loading) return;
        c.loading = true;
        c.server.refresh().then(function(r) {
            c.loading = false;
        }, function() {
            c.loading = false;
        });
    };

    c.goTo = function(page) {
        if (!page) return;
        window.location.href = '?id=' + encodeURIComponent(page) + '&student=' + (c.data.student ? c.data.student.id : '');
    };

    // Document click dismiss popover
    document.addEventListener('click', function(e) {
        var popover = document.getElementById('studentNotifPopover');
        var bell = document.getElementById('studentNotifBell');
        if (popover && bell && !popover.contains(e.target) && !bell.contains(e.target)) {
            $scope.$apply(function() {
                c.showNotificationsPopover = false;
            });
        }
    });

};

sp_widget.css:
/* =========================================================
   CAMPUS360 STUDENT DASHBOARD
   PURPLE SIDEBAR
   NO VISIBLE SIDEBAR SCROLLBAR
   MAIN CONTENT SCROLLS NORMALLY
   ========================================================= */


/* =========================================================
   GLOBAL
   ========================================================= */

html,
body {

  width: 100% !important;
  height: 100% !important;

  margin: 0 !important;
  padding: 0 !important;

  overflow: hidden !important;
}


/* =========================================================
   CAMPUS360 ROOT
   ========================================================= */

.campus360-app {

  position: fixed !important;

  inset: 0 !important;

  width: 100vw !important;
  height: 100vh !important;

  min-width: 100vw !important;
  min-height: 100vh !important;

  max-width: 100vw !important;
  max-height: 100vh !important;

  margin: 0 !important;
  padding: 0 !important;

  display: flex !important;

  overflow: hidden !important;

  background: #f3f6fb !important;

  color: #101828 !important;

  font-family:
    Inter,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Arial,
    sans-serif !important;

  -webkit-font-smoothing: antialiased;

  box-sizing: border-box !important;

  z-index: 1 !important;
}


.campus360-app *,
.campus360-app *:before,
.campus360-app *:after {

  box-sizing: border-box !important;
}


/* =========================================================
   SERVICENOW DEFAULT NAVBAR
   HIDE COMPLETELY
   ========================================================= */

body:has(.campus360-app) #sp-header,
body:has(.campus360-app) header#sp-header,
body:has(.campus360-app) .sp-header,
body:has(.campus360-app) .sp-header-bar,
body:has(.campus360-app) .sp-navbar,
body:has(.campus360-app) #sp-nav,
body:has(.campus360-app) #sp-nav-bar,
body:has(.campus360-app) .sp-nav-bar,
body:has(.campus360-app) .portal-header,
body:has(.campus360-app) header[role="banner"],
body:has(.campus360-app) nav[role="navigation"],
body:has(.campus360-app) .navbar,
body:has(.campus360-app) .navbar-default,
body:has(.campus360-app) .navbar-inverse,
body:has(.campus360-app) nav.navbar {

  display: none !important;

  visibility: hidden !important;
  opacity: 0 !important;

  width: 0 !important;
  height: 0 !important;

  min-width: 0 !important;
  min-height: 0 !important;

  max-width: 0 !important;
  max-height: 0 !important;

  margin: 0 !important;
  padding: 0 !important;

  border: 0 !important;

  overflow: hidden !important;
}


/* =========================================================
   SERVICENOW WRAPPERS
   ========================================================= */

body:has(.campus360-app) .page,
body:has(.campus360-app) #sp-container,
body:has(.campus360-app) #sp-page,
body:has(.campus360-app) .sp-page,
body:has(.campus360-app) .sp-container,
body:has(.campus360-app) .container,
body:has(.campus360-app) .container-fluid,
body:has(.campus360-app) .row,
body:has(.campus360-app) [class*="col-"] {

  width: 100% !important;
  max-width: none !important;

  margin: 0 !important;
  padding: 0 !important;

  border: 0 !important;
}


body:has(.campus360-app) {

  margin: 0 !important;
  padding: 0 !important;

  width: 100% !important;
  height: 100% !important;

  overflow: hidden !important;
}


/* =========================================================
   SIDEBAR
   IMPORTANT:
   SIDEBAR ITSELF DOES NOT SCROLL.
   ONLY NAVIGATION AREA SCROLLS.
   ========================================================= */

.campus360-sidebar {

  width: 250px !important;
  min-width: 250px !important;
  max-width: 250px !important;

  height: 100vh !important;
  min-height: 0 !important;
  max-height: 100vh !important;

  flex: 0 0 250px !important;

  display: flex !important;
  flex-direction: column !important;

  position: relative !important;

  /* THIS REMOVES THE DIRTY OUTER SCROLLBAR */
  overflow: hidden !important;

  background:
    linear-gradient(
      180deg,
      #130d2f 0%,
      #160d38 48%,
      #100a29 100%
    ) !important;

  border-right:
    1px solid #2d2157 !important;

  color: #ffffff !important;

  z-index: 20 !important;

  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}


.campus360-sidebar::-webkit-scrollbar {

  width: 0 !important;
  height: 0 !important;

  display: none !important;
}


/* =========================================================
   BRAND
   ========================================================= */

.sidebar-brand {

  height: 78px !important;
  min-height: 78px !important;

  flex: 0 0 78px !important;

  padding: 0 18px !important;

  display: flex !important;
  align-items: center !important;

  gap: 12px !important;

  border-bottom:
    1px solid rgba(255,255,255,.08) !important;
}


.brand-mark {

  width: 40px !important;
  height: 40px !important;

  min-width: 40px !important;

  border-radius: 11px !important;

  background:
    linear-gradient(
      135deg,
      #7c3aed,
      #9333ea
    ) !important;

  color: #ffffff !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  font-size: 21px !important;
  font-weight: 900 !important;

  box-shadow:
    0 7px 18px rgba(124,58,237,.34) !important;
}


.brand-name {

  font-size: 18px !important;

  font-weight: 900 !important;

  color: #ffffff !important;
}


.brand-subtitle {

  margin-top: 2px !important;

  font-size: 11px !important;

  color: #c4b5fd !important;

  font-weight: 750 !important;
}


/* =========================================================
   STUDENT MINI PROFILE
   ========================================================= */

.student-mini-profile {

  margin:
    16px 12px 10px !important;

  padding: 12px !important;

  min-height: 64px !important;

  flex: 0 0 auto !important;

  border:
    1px solid #3c2b69 !important;

  border-radius: 14px !important;

  display: flex !important;
  align-items: center !important;

  gap: 10px !important;

  text-decoration: none !important;

  background:
    linear-gradient(
      145deg,
      #1f1448,
      #21154d
    ) !important;

  box-shadow:
    0 6px 18px rgba(0,0,0,.16) !important;

  transition:
    .2s ease !important;
}


.student-mini-profile:hover {

  border-color:
    #5b3ea2 !important;

  background:
    linear-gradient(
      145deg,
      #271957,
      #2b1c61
    ) !important;

  box-shadow:
    0 8px 20px rgba(124,58,237,.18) !important;
}


.student-avatar {

  width: 40px !important;
  height: 40px !important;

  flex: 0 0 40px !important;

  border-radius: 50% !important;

  background:
    linear-gradient(
      135deg,
      #8b5cf6,
      #7c3aed
    ) !important;

  color: #ffffff !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  box-shadow:
    0 6px 16px rgba(124,58,237,.28) !important;
}


.student-avatar svg {

  width: 22px !important;
  height: 22px !important;

  fill: none !important;

  stroke: #ffffff !important;

  stroke-width: 1.8 !important;

  stroke-linecap: round !important;
  stroke-linejoin: round !important;
}


.student-mini-info {

  min-width: 0 !important;

  flex: 1 !important;
}


.student-mini-name {

  font-size: 13px !important;

  font-weight: 850 !important;

  color: #ffffff !important;

  white-space: nowrap !important;

  overflow: hidden !important;

  text-overflow: ellipsis !important;
}


.student-mini-id {

  margin-top: 3px !important;

  font-size: 10px !important;

  color: #b9add7 !important;

  font-weight: 600 !important;
}


.profile-arrow {

  color: #aaa0c2 !important;

  font-size: 20px !important;

  font-weight: 500 !important;
}


/* =========================================================
   NAVIGATION
   THIS IS THE ONLY SCROLLABLE PART OF SIDEBAR
   SCROLLBAR IS INVISIBLE
   ========================================================= */

.campus360-nav {

  flex: 1 1 auto !important;

  min-height: 0 !important;

  height: auto !important;

  padding:
    3px 8px 8px !important;

  overflow-y: auto !important;

  overflow-x: hidden !important;

  background: transparent !important;

  scrollbar-width: none !important;

  -ms-overflow-style: none !important;
}


/* CHROME / EDGE / SAFARI */

.campus360-nav::-webkit-scrollbar {

  width: 0 !important;
  height: 0 !important;

  display: none !important;
}

.campus360-nav::-webkit-scrollbar-track {

  background: transparent !important;
}

.campus360-nav::-webkit-scrollbar-thumb {

  background: transparent !important;
}


/* =========================================================
   SECTION TITLE
   ========================================================= */

.nav-section-title {

  padding:
    18px 9px 8px !important;

  font-size: 10px !important;

  letter-spacing:
    .11em !important;

  font-weight: 900 !important;

  color: #9f94bd !important;
}


/* =========================================================
   NAV ITEM
   ========================================================= */

.nav-item {

  position: relative !important;

  display: flex !important;

  align-items: center !important;

  gap: 12px !important;

  min-height: 46px !important;

  padding:
    9px 12px !important;

  margin:
    3px 0 !important;

  border-radius: 11px !important;

  color: #ddd8e8 !important;

  background: transparent !important;

  font-size: 14px !important;

  font-weight: 750 !important;

  text-decoration:
    none !important;

  transition:
    background .2s ease,
    color .2s ease,
    transform .2s ease !important;
}


.nav-item:hover {

  color: #ffffff !important;

  background:
    rgba(124,58,237,.16) !important;

  transform:
    translateX(2px) !important;
}


.nav-item.active {

  color: #ffffff !important;

  background:
    linear-gradient(
      90deg,
      #7c3aed 0%,
      #8b3ff2 100%
    ) !important;

  font-weight: 900 !important;

  box-shadow:
    0 7px 18px rgba(124,58,237,.28) !important;
}


.nav-item.active:before {

  content: "";

  position: absolute !important;

  left: 0 !important;

  top: 8px !important;
  bottom: 8px !important;

  width: 4px !important;

  border-radius:
    0 4px 4px 0 !important;

  background: #c4b5fd !important;
}


/* =========================================================
   NAV ICON
   ========================================================= */

.nav-icon {

  width: 24px !important;
  height: 24px !important;

  flex: 0 0 24px !important;

  display: flex !important;

  align-items: center !important;
  justify-content: center !important;

  color: #b8aecb !important;
}


.nav-icon svg {

  width: 21px !important;
  height: 21px !important;

  fill: none !important;

  stroke: currentColor !important;

  stroke-width: 1.8 !important;

  stroke-linecap: round !important;
  stroke-linejoin: round !important;
}


.nav-item:hover .nav-icon {

  color: #ffffff !important;
}


.nav-item.active .nav-icon {

  color: #ffffff !important;
}


/* =========================================================
   NAV COUNTS
   ========================================================= */

.nav-count {

  margin-left: auto !important;

  min-width: 23px !important;

  height: 23px !important;

  padding: 0 6px !important;

  border-radius: 50% !important;

  background:
    rgba(139,92,246,.30) !important;

  color: #ddd6fe !important;

  border:
    1px solid rgba(196,181,253,.08) !important;

  font-size: 11px !important;

  font-weight: 900 !important;

  display: flex !important;

  align-items: center !important;
  justify-content: center !important;
}


/* =========================================================
   SIDEBAR FOOTER
   FIXED AT BOTTOM
   ========================================================= */

.sidebar-footer {

  flex: 0 0 auto !important;

  padding: 12px !important;

  border-top:
    1px solid rgba(255,255,255,.08) !important;

  background:
    linear-gradient(
      180deg,
      #120c2d,
      #100a29
    ) !important;
}


.journey-mini {

  padding: 13px !important;

  border-radius: 12px !important;

  background:
    linear-gradient(
      145deg,
      #1e143f,
      #21164a
    ) !important;

  border:
    1px solid #382963 !important;
}


.journey-mini-label {

  font-size: 9px !important;

  font-weight: 900 !important;

  color: #a69abd !important;

  letter-spacing: .08em !important;
}


.journey-mini-progress {

  height: 7px !important;

  margin-top: 10px !important;

  border-radius: 8px !important;

  background: #30234f !important;

  overflow: hidden !important;
}


.journey-mini-fill {

  height: 100% !important;

  border-radius: 8px !important;

  background:
    linear-gradient(
      90deg,
      #7c3aed,
      #a855f7
    ) !important;
}


.journey-mini-score {

  margin-top: 7px !important;

  font-size: 11px !important;

  color: #c1b7d3 !important;

  font-weight: 700 !important;
}


/* =========================================================
   MAIN
   MAIN AREA IS NOW THE SCROLLABLE AREA
   ========================================================= */

.campus360-main {

  flex: 1 1 auto !important;

  min-width: 0 !important;
  min-height: 0 !important;

  width:
    calc(100vw - 250px) !important;

  height: 100vh !important;

  display: flex !important;

  flex-direction: column !important;

  overflow-y: auto !important;

  overflow-x: hidden !important;

  background: #f3f6fb !important;

  scrollbar-width: none !important;

  -ms-overflow-style: none !important;
}


.campus360-main::-webkit-scrollbar {

  width: 0 !important;
  height: 0 !important;

  display: none !important;
}


/* =========================================================
   TOPBAR
   ========================================================= */

.topbar {

  height: 68px !important;

  min-height: 68px !important;

  flex: 0 0 68px !important;

  padding:
    0 26px !important;

  background: #ffffff !important;

  border-bottom:
    1px solid #dfe4ec !important;

  display: flex !important;

  align-items: center !important;

  justify-content: space-between !important;

  position: sticky !important;

  top: 0 !important;

  z-index: 100 !important;
}


.search-box {

  width: 415px !important;

  height: 40px !important;

  border:
    1px solid #cbd5ff !important;

  border-radius: 11px !important;

  background: #ffffff !important;

  display: flex !important;

  align-items: center !important;

  gap: 9px !important;

  padding:
    0 13px !important;

  color: #64748b !important;

  font-size: 12px !important;

  font-weight: 500 !important;
}


.search-box svg {

  width: 16px !important;
  height: 16px !important;

  fill: none !important;

  stroke: #5662ee !important;

  stroke-width: 1.8 !important;

  stroke-linecap: round !important;
}


.topbar-right {

  display: flex !important;

  align-items: center !important;

  gap: 10px !important;
}


.icon-button,
.notification-button {

  width: 39px !important;
  height: 39px !important;

  border:
    1px solid #dce2ea !important;

  background: #ffffff !important;

  border-radius: 50% !important;

  display: flex !important;

  align-items: center !important;
  justify-content: center !important;

  position: relative !important;

  cursor: pointer !important;

  transition:
    .2s ease !important;
}


.icon-button:hover,
.notification-button:hover {

  background: #f1efff !important;

  border-color: #bcb5ff !important;
}


.icon-button svg {

  width: 17px !important;
  height: 17px !important;

  fill: none !important;

  stroke: #4f46e5 !important;

  stroke-width: 1.7 !important;

  stroke-linecap: round !important;

  stroke-linejoin: round !important;
}


.notification-button {

  border-color: #d9ddff !important;
}


.notification-button svg {

  color: #4f46e5 !important;
}


/* =========================================================
   NOTIFICATION
   ========================================================= */

.notification-badge {

  position: absolute !important;

  top: -2px !important;
  right: -2px !important;

  background: #ef4444 !important;

  color: #ffffff !important;

  font-size: 10px !important;

  font-weight: 700 !important;

  padding: 2px 5px !important;

  border-radius: 10px !important;

  min-width: 16px !important;

  text-align: center !important;

  border: 1.5px solid #ffffff !important;
}


.student-notif-popover {

  position: absolute !important;

  top: 45px !important;
  right: 0 !important;

  width: 380px !important;

  background: #ffffff !important;

  border:
    1px solid #e5e7eb !important;

  border-radius: 12px !important;

  box-shadow:
    0 10px 25px -5px rgba(0,0,0,.15),
    0 8px 10px -6px rgba(0,0,0,.10) !important;

  z-index: 1050 !important;

  overflow: hidden !important;

  font-family: inherit !important;

  animation:
    fadeInPopover .2s ease-in-out !important;
}


@keyframes fadeInPopover {

  from {
    opacity: 0;
    transform: translateY(-8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }

}


.snotif-header {

  display: flex !important;

  justify-content: space-between !important;

  align-items: center !important;

  padding:
    14px 16px !important;

  background: #f9fafb !important;

  border-bottom:
    1px solid #e5e7eb !important;
}


.snotif-title {

  font-size: 14px !important;

  font-weight: 700 !important;

  color: #111827 !important;

  display: flex !important;

  align-items: center !important;

  gap: 8px !important;
}


.snotif-count-pill {

  background: #fee2e2 !important;

  color: #dc2626 !important;

  font-size: 11px !important;

  font-weight: 600 !important;

  padding: 2px 8px !important;

  border-radius: 12px !important;
}


.snotif-clear-all {

  background: none !important;

  border: none !important;

  color: #6b7280 !important;

  font-size: 12px !important;

  font-weight: 600 !important;

  cursor: pointer !important;
}


.snotif-clear-all:hover {

  color: #ef4444 !important;
}


.snotif-tabs {

  display: flex !important;

  background: #ffffff !important;

  border-bottom:
    1px solid #f3f4f6 !important;

  padding:
    4px 8px 0 8px !important;
}


.snotif-tab {

  flex: 1 !important;

  background: none !important;

  border: none !important;

  border-bottom:
    2px solid transparent !important;

  padding:
    8px 4px !important;

  font-size: 11px !important;

  font-weight: 600 !important;

  color: #6b7280 !important;

  cursor: pointer !important;
}


.snotif-tab.active {

  color: #4f46e5 !important;

  border-bottom-color:
    #4f46e5 !important;
}


.snotif-body {

  max-height: 340px !important;

  overflow-y: auto !important;

  padding: 8px !important;

  scrollbar-width: none !important;

  -ms-overflow-style: none !important;
}


.snotif-body::-webkit-scrollbar {

  width: 0 !important;
  height: 0 !important;

  display: none !important;
}


.snotif-empty {

  text-align: center !important;

  padding:
    24px 12px !important;

  color: #9ca3af !important;
}


.snotif-empty i {

  font-size: 28px !important;

  color: #10b981 !important;

  margin-bottom: 8px !important;
}


.snotif-card {

  display: flex !important;

  gap: 12px !important;

  padding: 12px !important;

  border-radius: 8px !important;

  background: #f9fafb !important;

  margin-bottom: 8px !important;

  border:
    1px solid #f3f4f6 !important;

  transition:
    all .15s ease !important;
}


.snotif-card:hover {

  background: #ffffff !important;

  border-color: #e5e7eb !important;

  box-shadow:
    0 2px 4px rgba(0,0,0,.05) !important;
}


.snotif-card.opportunity_deadline {

  border-left:
    4px solid #ef4444 !important;

  background: #fef2f2 !important;
}


.snotif-card.interview {

  border-left:
    4px solid #3b82f6 !important;
}


.snotif-card.assessment {

  border-left:
    4px solid #8b5cf6 !important;
}


.snotif-card.shortlisted {

  border-left:
    4px solid #10b981 !important;
}


.snotif-icon {

  font-size: 16px !important;

  color: #4f46e5 !important;

  margin-top: 2px !important;
}


.snotif-card.opportunity_deadline .snotif-icon {
  color: #ef4444 !important;
}


.snotif-card.interview .snotif-icon {
  color: #3b82f6 !important;
}


.snotif-card.shortlisted .snotif-icon {
  color: #10b981 !important;
}


.snotif-content {

  flex: 1 !important;
}


.snotif-msg {

  font-size: 12px !important;

  font-weight: 500 !important;

  color: #1f2937 !important;

  line-height: 1.4 !important;

  margin-bottom: 4px !important;
}


.snotif-meta {

  font-size: 10px !important;

  color: #6b7280 !important;

  margin-bottom: 6px !important;
}


.snotif-actions {

  display: flex !important;

  gap: 8px !important;

  margin-top: 6px !important;
}


.sbtn {

  border: none !important;

  border-radius: 6px !important;

  padding:
    4px 8px !important;

  font-size: 10px !important;

  font-weight: 600 !important;

  cursor: pointer !important;

  display: inline-flex !important;

  align-items: center !important;

  gap: 4px !important;
}


.sbtn-ignore {

  background: #fee2e2 !important;

  color: #dc2626 !important;
}


.sbtn-ignore:hover {

  background: #fca5a5 !important;
}


.sbtn-dismiss {

  background: #e5e7eb !important;

  color: #374151 !important;
}


.sbtn-dismiss:hover {

  background: #d1d5db !important;
}


/* =========================================================
   TOP PROFILE
   ========================================================= */

.top-profile {

  display: flex !important;

  align-items: center !important;

  gap: 9px !important;

  text-decoration: none !important;

  padding-left: 2px !important;
}


.top-student-icon {

  width: 39px !important;
  height: 39px !important;

  border-radius: 50% !important;

  background: #e8e5ff !important;

  border:
    1px solid #9b94ff !important;

  display: flex !important;

  align-items: center !important;
  justify-content: center !important;
}


.top-student-icon svg {

  width: 21px !important;
  height: 21px !important;

  fill: none !important;

  stroke: #4f46e5 !important;

  stroke-width: 1.8 !important;

  stroke-linecap: round !important;

  stroke-linejoin: round !important;
}


.top-profile-text {

  display: flex !important;

  flex-direction: column !important;
}


.top-profile-name {

  font-size: 13px !important;

  font-weight: 900 !important;

  color: #101828 !important;
}


.top-profile-id {

  font-size: 9px !important;

  color: #667085 !important;

  font-weight: 600 !important;

  margin-top: 2px !important;
}


.top-profile-chevron {

  font-size: 13px !important;

  color: #667085 !important;

  margin-left: 3px !important;
}


/* =========================================================
   CONTENT
   ========================================================= */

.dashboard-content {

  width: 100% !important;

  max-width: none !important;

  margin: 0 !important;

  padding:
    28px 30px 22px !important;

  box-sizing: border-box !important;
}


/* =========================================================
   HEADER
   ========================================================= */

.dashboard-header {

  display: flex !important;

  justify-content: space-between !important;

  align-items: center !important;

  gap: 25px !important;

  margin-bottom: 18px !important;

  padding:
    25px 27px !important;

  border:
    1px solid #dce3f0 !important;

  border-radius: 18px !important;

  background:
    linear-gradient(
      110deg,
      #eef3ff 0%,
      #f5f2ff 100%
    ) !important;
}


.eyebrow,
.card-eyebrow {

  margin-bottom: 8px !important;

  font-size: 10px !important;

  font-weight: 950 !important;

  color: #5146e5 !important;

  letter-spacing: .13em !important;
}


.dashboard-header h1 {

  margin: 0 !important;

  font-size: 31px !important;

  line-height: 1.15 !important;

  font-weight: 950 !important;

  letter-spacing: -.025em !important;

  color: #0b1220 !important;
}


.dashboard-header p {

  margin: 8px 0 0 !important;

  max-width: 730px !important;

  font-size: 13px !important;

  line-height: 1.55 !important;

  color: #344054 !important;

  font-weight: 600 !important;
}


.student-context {

  min-width: 260px !important;

  padding:
    13px 18px !important;

  border:
    1px solid #dfe3ec !important;

  border-radius: 14px !important;

  background: #ffffff !important;

  display: flex !important;

  align-items: center !important;

  gap: 11px !important;

  box-shadow:
    0 6px 17px rgba(16,24,40,.05) !important;
}


.context-icon {

  width: 38px !important;
  height: 38px !important;

  border-radius: 50% !important;

  background: #ffb52e !important;

  display: flex !important;

  align-items: center !important;
  justify-content: center !important;
}


.context-icon svg {

  width: 21px !important;
  height: 21px !important;

  fill: #ffffff !important;

  stroke: none !important;
}


.context-label {

  display: block !important;

  font-size: 8px !important;

  color: #98a2b3 !important;

  font-weight: 900 !important;
}


.student-context strong {

  display: block !important;

  margin-top: 2px !important;

  font-size: 12px !important;

  color: #101828 !important;

  font-weight: 900 !important;
}


/* =========================================================
   KPI GRID
   ========================================================= */

.kpi-grid {

  display: grid !important;

  grid-template-columns:
    repeat(4,minmax(0,1fr)) !important;

  gap: 14px !important;

  margin-bottom: 17px !important;
}


.kpi-card {

  display: block !important;

  min-height: 151px !important;

  padding: 19px !important;

  border-radius: 16px !important;

  text-decoration: none !important;

  border:
    1px solid transparent !important;

  transition:
    transform .2s ease,
    box-shadow .2s ease !important;
}


.kpi-card:hover {

  transform: translateY(-3px) !important;

  box-shadow:
    0 14px 30px rgba(16,24,40,.12) !important;
}


.kpi-top,
.kpi-bottom {

  display: flex !important;

  align-items: center !important;

  justify-content: space-between !important;
}


.kpi-label {

  font-size: 14px !important;

  font-weight: 900 !important;

  color: #172033 !important;
}


.kpi-icon {

  width: 38px !important;
  height: 38px !important;

  border-radius: 10px !important;

  background: rgba(255,255,255,.92) !important;

  display: flex !important;

  align-items: center !important;
  justify-content: center !important;

  box-shadow:
    0 4px 11px rgba(16,24,40,.10) !important;
}


.kpi-icon svg {

  width: 20px !important;
  height: 20px !important;

  fill: none !important;

  stroke: currentColor !important;

  stroke-width: 2 !important;

  stroke-linecap: round !important;

  stroke-linejoin: round !important;
}


.kpi-value {

  margin:
    14px 0 8px !important;

  font-size: 36px !important;

  line-height: 1 !important;

  font-weight: 950 !important;

  letter-spacing: -.035em !important;

  color: #07101f !important;
}


.kpi-value span {

  font-size: 17px !important;

  font-weight: 850 !important;

  margin-left: 2px !important;
}


.kpi-bottom {

  font-size: 10px !important;

  color: #344054 !important;

  font-weight: 700 !important;
}


.kpi-bottom strong {

  font-weight: 900 !important;

  color: #172033 !important;
}


.kpi-link {

  font-size: 11px !important;

  font-weight: 950 !important;
}


/* =========================================================
   KPI COLORS
   ========================================================= */

.kpi-purple {

  background:
    linear-gradient(
      135deg,
      #e8fff7 0%,
      #d0f7ea 100%
    ) !important;

  border-color: #9debd5 !important;
}


.kpi-purple .kpi-icon,
.kpi-purple .kpi-link {

  color: #079b7d !important;
}


.kpi-purple .kpi-value {

  color: #07101f !important;
}


.kpi-blue {

  background:
    linear-gradient(
      135deg,
      #edf5ff 0%,
      #dbeaff 100%
    ) !important;

  border-color: #b5d3ff !important;
}


.kpi-blue .kpi-icon,
.kpi-blue .kpi-link {

  color: #2563eb !important;
}


.kpi-indigo {

  background:
    linear-gradient(
      135deg,
      #f4edff 0%,
      #eadcff 100%
    ) !important;

  border-color: #d8c2ff !important;
}


.kpi-indigo .kpi-icon,
.kpi-indigo .kpi-link {

  color: #7445e8 !important;
}


.kpi-orange {

  background:
    linear-gradient(
      135deg,
      #fff5f1 0%,
      #ffe4dc 100%
    ) !important;

  border-color: #ffcabc !important;
}


.kpi-orange .kpi-icon,
.kpi-orange .kpi-link {

  color: #f04438 !important;
}


/* =========================================================
   DASHBOARD GRID
   ========================================================= */

.dashboard-grid {

  display: grid !important;

  grid-template-columns:
    minmax(0,1.55fr)
    minmax(360px,.75fr) !important;

  gap: 16px !important;

  margin-bottom: 17px !important;
}


.dashboard-card {

  background: #ffffff !important;

  border:
    1px solid #dce3ec !important;

  border-radius: 17px !important;

  padding: 20px !important;

  box-shadow:
    0 5px 18px rgba(16,24,40,.045) !important;
}


.dashboard-card:hover {

  box-shadow:
    0 9px 25px rgba(16,24,40,.07) !important;
}


.card-header {

  display: flex !important;

  align-items: flex-start !important;

  justify-content: space-between !important;

  gap: 15px !important;

  margin-bottom: 17px !important;
}


.card-header h2 {

  margin: 0 !important;

  font-size: 20px !important;

  font-weight: 950 !important;

  letter-spacing: -.015em !important;

  color: #0b1220 !important;
}


.text-link {

  font-size: 11px !important;

  color: #5146e5 !important;

  font-weight: 950 !important;

  text-decoration: none !important;
}


/* =========================================================
   READINESS
   ========================================================= */

.readiness-content {

  display: grid !important;

  grid-template-columns:
    210px 1fr !important;

  gap: 25px !important;

  align-items: center !important;
}


.readiness-score {

  text-align: center !important;

  padding: 10px !important;

  border-radius: 13px !important;

  background: #f8fafc !important;
}


.score-ring {

  width: 145px !important;
  height: 145px !important;

  margin: 0 auto !important;

  border-radius: 50% !important;

  background:
    conic-gradient(
      #20a8d8 calc(var(--score,75) * 1%),
      #e1e8f0 0
    ) !important;

  display: flex !important;

  align-items: center !important;
  justify-content: center !important;

  position: relative !important;
}


.score-ring:after {

  content: "";

  position: absolute !important;

  inset: 10px !important;

  border-radius: 50% !important;

  background: #ffffff !important;
}


.score-inner {

  position: relative !important;

  z-index: 2 !important;

  display: flex !important;

  align-items: baseline !important;
}


.score-inner strong {

  font-size: 39px !important;

  font-weight: 950 !important;

  color: #0b1220 !important;

  letter-spacing: -.04em !important;
}


.score-inner span {

  margin-left: 3px !important;

  font-size: 11px !important;

  color: #667085 !important;

  font-weight: 750 !important;
}


.score-caption {

  margin-top: 8px !important;

  font-size: 10px !important;

  font-weight: 900 !important;

  color: #344054 !important;
}


.current-risk-badge {

  display: inline-flex !important;

  margin-top: 8px !important;

  padding: 5px 9px !important;

  border-radius: 15px !important;

  font-size: 9px !important;

  font-weight: 900 !important;
}


.risk-low {
  background: #d1fae5;
  color: #047857;
}


.risk-medium {
  background: #fff0bf;
  color: #a15c00;
}


.risk-high {
  background: #ffe0e0;
  color: #c62828;
}


.readiness-metrics {

  display: flex !important;

  flex-direction: column !important;

  gap: 14px !important;
}


.metric-info {

  display: flex !important;

  align-items: center !important;

  justify-content: space-between !important;

  margin-bottom: 6px !important;
}


.metric-name {

  font-size: 11px !important;

  color: #344054 !important;

  font-weight: 800 !important;
}


.metric-info strong {

  font-size: 11px !important;

  color: #101828 !important;

  font-weight: 950 !important;
}


.metric-bar {

  height: 8px !important;

  border-radius: 10px !important;

  background: #e9edf3 !important;

  overflow: hidden !important;
}


.metric-fill {

  height: 100% !important;

  border-radius: 10px !important;
}


.metric-fill.participation {

  background:
    linear-gradient(
      90deg,
      #3285ef,
      #4f46e5
    ) !important;
}


.metric-fill.technical {

  background:
    linear-gradient(
      90deg,
      #18b8d5,
      #398df0
    ) !important;
}


.metric-fill.problem {

  background:
    linear-gradient(
      90deg,
      #a34cf2,
      #6558e9
    ) !important;
}


.metric-fill.communication {

  background:
    linear-gradient(
      90deg,
      #fdbb20,
      #ff7517
    ) !important;
}


.missed-row {

  display: flex !important;

  align-items: center !important;

  justify-content: space-between !important;

  margin-top: 1px !important;

  color: #667085 !important;

  font-size: 10px !important;

  font-weight: 700 !important;
}


.missed-row strong {

  min-width: 24px !important;

  height: 24px !important;

  display: flex !important;

  align-items: center !important;

  justify-content: center !important;

  border-radius: 7px !important;

  background: #f0f3f7 !important;

  color: #344054 !important;

  font-size: 10px !important;

  font-weight: 900 !important;
}


/* =========================================================
   INTELLIGENCE
   ========================================================= */

.intelligence-card {

  padding: 20px !important;

  position: relative !important;

  overflow: hidden !important;
}


.intelligence-header {

  margin-bottom: 4px !important;
}


.intelligence-status {

  padding: 5px 9px !important;

  border-radius: 10px !important;

  background: #d1fae5 !important;

  color: #047857 !important;

  font-size: 9px !important;

  font-weight: 900 !important;
}


.robot-container {

  height: 90px !important;

  display: flex !important;

  align-items: center !important;

  justify-content: center !important;

  margin: 0 0 7px !important;
}


.robot-glow {

  width: 76px !important;
  height: 76px !important;

  border-radius: 18px !important;

  background:
    linear-gradient(
      145deg,
      #ffffff,
      #f3f0ff
    ) !important;

  border:
    1px solid #d9d4ff !important;

  box-shadow:
    0 8px 22px rgba(79,70,229,.14) !important;

  display: flex !important;

  align-items: center !important;
  justify-content: center !important;

  overflow: hidden !important;
}


.robot-image {

  width: 100% !important;
  height: 100% !important;

  object-fit: cover !important;

  display: block !important;
}


.intelligence-box {

  border-radius: 13px !important;

  padding: 13px !important;

  margin-top: 9px !important;

  border:
    1px solid #dce3ec !important;
}


.summary-box {

  background: #f9fbff !important;

  border-color: #dce5f4 !important;
}


.intelligence-box-label {

  display: block !important;

  font-size: 9px !important;

  color: #5146e5 !important;

  font-weight: 950 !important;

  letter-spacing: .08em !important;
}


.intelligence-box p {

  margin: 8px 0 0 !important;

  font-size: 10px !important;

  line-height: 1.55 !important;

  color: #344054 !important;

  font-weight: 600 !important;
}


.primary-gap-box {

  background: #fffaf0 !important;

  border-color: #f5d58b !important;
}


.gap-header {

  display: flex !important;

  align-items: center !important;

  justify-content: space-between !important;

  gap: 10px !important;

  margin-bottom: 7px !important;
}


.gap-score {

  padding: 4px 7px !important;

  border-radius: 9px !important;

  background: #ffe7a5 !important;

  color: #985500 !important;

  font-size: 8px !important;

  font-weight: 950 !important;
}


.primary-gap-box > strong {

  display: block !important;

  color: #101828 !important;

  font-size: 13px !important;

  font-weight: 950 !important;
}


.gap-tags {

  display: flex !important;

  gap: 6px !important;

  margin-top: 8px !important;

  flex-wrap: wrap !important;
}


.gap-tags span {

  padding: 5px 7px !important;

  border:
    1px solid #edcf93 !important;

  border-radius: 6px !important;

  background: #ffffff !important;

  color: #8a4b00 !important;

  font-size: 8px !important;

  font-weight: 800 !important;
}


.intelligence-action {

  margin-top: 10px !important;

  min-height: 34px !important;

  padding: 8px 12px !important;

  border-radius: 9px !important;

  background: #5146e5 !important;

  color: #ffffff !important;

  display: flex !important;

  align-items: center !important;

  justify-content: space-between !important;

  text-decoration: none !important;

  font-size: 10px !important;

  font-weight: 900 !important;

  box-shadow:
    0 6px 14px rgba(79,70,229,.18) !important;

  transition: .2s ease !important;
}


.intelligence-action:hover {

  background: #4338ca !important;

  transform: translateY(-1px) !important;
}


/* =========================================================
   INTERVENTION
   ========================================================= */

.intervention-card {

  margin-bottom: 17px !important;

  padding: 20px !important;

  overflow: hidden !important;
}


.intervention-header {

  margin-bottom: 14px !important;
}


.intervention-header h2 {

  font-size: 21px !important;

  color: #07101f !important;

  font-weight: 950 !important;
}


.status-badge {

  display: inline-flex !important;

  align-items: center !important;

  justify-content: center !important;

  padding: 6px 12px !important;

  border-radius: 20px !important;

  font-size: 9px !important;

  font-weight: 950 !important;
}


.status-completed {

  background: #c9f7df !important;

  color: #00845a !important;
}


.status-recommended {

  background: #fff0bd !important;

  color: #965b00 !important;
}


.status-progress {

  background: #dce9ff !important;

  color: #2454bd !important;
}


.intervention-main {

  display: flex !important;

  gap: 16px !important;

  padding: 18px !important;

  min-height: 105px !important;

  border-radius: 14px !important;

  background:
    linear-gradient(
      135deg,
      #f4efff 0%,
      #eee8ff 100%
    ) !important;

  border:
    1px solid #d8c8ff !important;

  position: relative !important;
}


.intervention-main:before {

  content: "";

  position: absolute !important;

  left: 0 !important;

  top: 12px !important;

  bottom: 12px !important;

  width: 5px !important;

  border-radius:
    0 5px 5px 0 !important;

  background:
    linear-gradient(
      180deg,
      #5947ed,
      #7b55f4
    ) !important;
}


.intervention-type-icon {

  width: 46px !important;
  height: 46px !important;

  min-width: 46px !important;

  border-radius: 12px !important;

  background: #5947ed !important;

  color: #ffffff !important;

  display: flex !important;

  align-items: center !important;
  justify-content: center !important;

  box-shadow:
    0 7px 17px rgba(89,71,237,.25) !important;
}


.intervention-type-icon svg {

  width: 22px !important;
  height: 22px !important;

  fill: #ffffff !important;
}


.intervention-label {

  font-size: 9px !important;

  color: #5b45e8 !important;

  font-weight: 950 !important;

  letter-spacing: .08em !important;
}


.intervention-main h3 {

  margin:
    4px 0 5px !important;

  font-size: 18px !important;

  color: #07101f !important;

  font-weight: 950 !important;
}


.intervention-main p {

  margin: 0 !important;

  max-width: 1100px !important;

  font-size: 10px !important;

  line-height: 1.6 !important;

  color: #344054 !important;

  font-weight: 650 !important;
}


.intervention-grid {

  display: grid !important;

  grid-template-columns:
    repeat(4,minmax(0,1fr)) !important;

  gap: 11px !important;

  margin-top: 11px !important;
}


.intervention-detail {

  min-height: 76px !important;

  padding: 14px !important;

  border-radius: 11px !important;

  display: flex !important;

  flex-direction: column !important;

  justify-content: center !important;

  border:
    1px solid #dce3ec !important;

  transition: .2s ease !important;
}


.intervention-detail:hover {

  transform: translateY(-2px) !important;

  box-shadow:
    0 7px 16px rgba(16,24,40,.07) !important;
}


.intervention-detail span {

  font-size: 8px !important;

  color: #667085 !important;

  font-weight: 950 !important;

  letter-spacing: .08em !important;
}


.intervention-detail strong {

  margin-top: 6px !important;

  font-size: 16px !important;

  color: #07101f !important;

  font-weight: 950 !important;
}


.training-detail {

  background: #f7faff !important;

  border-color: #cbdcf5 !important;
}


.training-detail strong {

  color: #173b8f !important;
}


.before-detail {

  background: #fffaf0 !important;

  border-color: #f7df9b !important;
}


.before-detail strong {

  color: #9a5a00 !important;

  font-size: 20px !important;
}


.after-detail {

  background: #effcf6 !important;

  border-color: #b7efd5 !important;
}


.after-detail strong {

  color: #087f5b !important;

  font-size: 20px !important;
}


.effectiveness-detail {

  background: #f2f4ff !important;

  border-color: #cbd2ff !important;
}


.effectiveness-detail strong {

  font-size: 20px !important;

  color: #5146e5 !important;
}


.positive-score {

  color: #00845a !important;
}


.neutral-score {

  color: #667085 !important;
}


.negative-score {

  color: #dc2626 !important;
}


.intervention-action {

  width: 175px !important;

  margin-top: 11px !important;

  margin-left: auto !important;

  display: flex !important;

  align-items: center !important;

  justify-content: space-between !important;

  padding: 10px 13px !important;

  border-radius: 9px !important;

  background: #5146e5 !important;

  color: #ffffff !important;

  text-decoration: none !important;

  font-size: 10px !important;

  font-weight: 950 !important;

  box-shadow:
    0 7px 15px rgba(79,70,229,.18) !important;

  transition: .2s ease !important;
}


.intervention-action:hover {

  background: #4338ca !important;

  transform: translateY(-1px) !important;
}


/* =========================================================
   EMPTY INTERVENTION
   ========================================================= */

.empty-intervention {

  margin-bottom: 17px !important;

  display: flex !important;

  align-items: center !important;

  gap: 15px !important;
}


.empty-icon {

  width: 45px !important;
  height: 45px !important;

  border-radius: 12px !important;

  background: #d1fae5 !important;

  color: #047857 !important;

  display: flex !important;

  align-items: center !important;
  justify-content: center !important;
}


.empty-icon svg {

  width: 22px !important;
  height: 22px !important;

  fill: none !important;

  stroke: currentColor !important;

  stroke-width: 2 !important;

  stroke-linecap: round !important;
  stroke-linejoin: round !important;
}


.empty-intervention h2 {

  margin: 0 !important;

  font-size: 19px !important;

  color: #07101f !important;

  font-weight: 950 !important;
}


.empty-intervention p {

  margin: 5px 0 0 !important;

  color: #667085 !important;

  font-size: 11px !important;

  font-weight: 600 !important;
}


.secondary-button {

  margin-left: auto !important;

  padding:
    10px 14px !important;

  border:
    1px solid #bbb3ff !important;

  border-radius: 9px !important;

  background: #ffffff !important;

  color: #5146e5 !important;

  text-decoration: none !important;

  font-size: 10px !important;

  font-weight: 950 !important;
}


/* =========================================================
   FOOTER
   ========================================================= */

.dashboard-footer {

  display: flex !important;

  align-items: center !important;

  justify-content: flex-start !important;

  padding:
    3px 1px 4px !important;

  color: #667085 !important;

  font-size: 9px !important;

  font-weight: 600 !important;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width:1250px) {

  .campus360-sidebar {

    width: 225px !important;
    min-width: 225px !important;
    max-width: 225px !important;

    flex-basis: 225px !important;
  }


  .campus360-main {

    width:
      calc(100vw - 225px) !important;
  }


  .kpi-grid {

    grid-template-columns:
      repeat(2,minmax(0,1fr)) !important;
  }


  .dashboard-grid {

    grid-template-columns:
      1fr !important;
  }


  .intelligence-card {

    min-height: auto !important;
  }

}


@media (max-width:900px) {

  .campus360-sidebar {

    width: 72px !important;
    min-width: 72px !important;
    max-width: 72px !important;

    flex-basis: 72px !important;
  }


  .campus360-main {

    width:
      calc(100vw - 72px) !important;
  }


  .brand-text,
  .student-mini-info,
  .profile-arrow,
  .nav-section-title,
  .nav-item > span:not(.nav-icon),
  .nav-count,
  .sidebar-footer {

    display: none !important;
  }


  .sidebar-brand {

    justify-content: center !important;

    padding: 0 !important;
  }


  .student-mini-profile {

    justify-content: center !important;

    padding: 9px !important;
  }


  .nav-item {

    justify-content: center !important;

    padding-left: 0 !important;
    padding-right: 0 !important;
  }


  .dashboard-content {

    padding: 20px !important;
  }


  .dashboard-header {

    flex-direction: column !important;

    align-items: flex-start !important;
  }


  .student-context {

    width: 100% !important;
  }


  .readiness-content {

    grid-template-columns:
      1fr !important;
  }

}


@media (max-width:650px) {

  .topbar {

    padding:
      0 13px !important;
  }


  .search-box {

    width: 220px !important;
  }


  .top-profile-text,
  .top-profile-chevron {

    display: none !important;
  }


  .kpi-grid {

    grid-template-columns:
      1fr !important;
  }


  .dashboard-header h1 {

    font-size: 25px !important;
  }


  .dashboard-header p {

    font-size: 12px !important;
  }


  .intervention-grid {

    grid-template-columns:
      1fr 1fr !important;
  }


  .intervention-main {

    flex-direction: column !important;
  }

}


@media (max-width:480px) {

  .campus360-sidebar {

    width: 62px !important;
    min-width: 62px !important;
    max-width: 62px !important;

    flex-basis: 62px !important;
  }


  .campus360-main {

    width:
      calc(100vw - 62px) !important;
  }


  .dashboard-content {

    padding: 14px !important;
  }


  .topbar {

    height: 62px !important;

    min-height: 62px !important;

    flex-basis: 62px !important;
  }


  .search-box {

    display: none !important;
  }


  .dashboard-grid {

    gap: 12px !important;
  }


  .intervention-grid {

    grid-template-columns:
      1fr !important;
  }


  .intervention-action {

    width: 100% !important;
  }


  .empty-intervention {

    align-items:
      flex-start !important;

    flex-wrap: wrap !important;
  }


  .secondary-button {

    margin-left: 0 !important;
  }

}


/* =========================================================
   FINAL SAFETY
   ========================================================= */

/*
   NO SCROLLBAR ON CAMPUS360 OUTER CONTAINER
*/
.campus360-app {

  overflow: hidden !important;

  margin-top: 0 !important;
  margin-bottom: 0 !important;
}


/*
   NO SCROLLBAR ON SIDEBAR
   BUT NAV REMAINS SCROLLABLE
*/
.campus360-sidebar {

  overflow: hidden !important;

  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}


.campus360-sidebar::-webkit-scrollbar {

  width: 0 !important;
  height: 0 !important;

  display: none !important;
}


/*
   INVISIBLE SIDEBAR NAV SCROLL
*/
.campus360-nav {

  overflow-y: auto !important;
  overflow-x: hidden !important;

  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}


.campus360-nav::-webkit-scrollbar {

  width: 0 !important;
  height: 0 !important;

  display: none !important;
}


/*
   MAIN PAGE SCROLL
   SCROLLBAR ALSO HIDDEN
*/
.campus360-main {

  overflow-y: auto !important;
  overflow-x: hidden !important;

  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}


.campus360-main::-webkit-scrollbar {

  width: 0 !important;
  height: 0 !important;

  display: none !important;
}


.campus360-app .dashboard-content {

  width: 100% !important;

  max-width: none !important;

  margin-left: 0 !important;
  margin-right: 0 !important;

  min-height: max-content !important;
}

sp_widget.script:
(function() {

    /*
     * ============================================================
     * CAMPUS360 STUDENT DASHBOARD - DYNAMIC SERVER SCRIPT
     * WITH FULL REAL NOTIFICATION FLOW & IGNORABLE DEADLINES
     * ============================================================
     */

    data.student = {
        id: "STU_TEST_001",
        name: "Student",
        email: "",
        batch: "",
        branch: "",
        initials: "ST"
    };

    data.readiness = {
        score: 0,
        risk: "Low",
        skillGap: "No Significant Gap",
        participation: 0,
        missedOpportunities: 0,
        recommendation: ""
    };

    data.counts = {
        applications: 0,
        interviews: 0,
        interventions: 0
    };

    data.intervention = {
        exists: false,
        type: "",
        status: "",
        training: "",
        reason: "",
        beforeScore: 0,
        afterScore: 0,
        effectiveness: 0
    };

    data.notifications = [];
    data.unreadCount = 0;
    data.aiWidget = $sp.getWidget('c4ae634574e703107f4410c9fee0cde5');

    function getInitials(name) {
        if (!name) return "ST";
        var parts = name.trim().split(/\s+/);
        if (parts.length === 1) return parts[0].substring(0, 2).toUpperCase();
        return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase();
    }

    function findStudent() {
        var requestedStudent = $sp.getParameter("student");
        var studentGR = new GlideRecord("x_snc_campus360_student_master");

        if (requestedStudent) {
            studentGR.addQuery("student_id", requestedStudent);
            studentGR.query();
            if (studentGR.next()) return studentGR;

            studentGR = new GlideRecord("x_snc_campus360_student_master");
            if (studentGR.get(requestedStudent)) return studentGR;
        }

        var email = gs.getUser().getEmail();
        if (email) {
            studentGR = new GlideRecord("x_snc_campus360_student_master");
            studentGR.addQuery("email", email);
            studentGR.query();
            if (studentGR.next()) return studentGR;
        }

        studentGR = new GlideRecord("x_snc_campus360_student_master");
        studentGR.addQuery("student_id", "STU_TEST_001");
        studentGR.query();
        if (studentGR.next()) return studentGR;

        return null;
    }

    var studentGR = findStudent();
    var studentSysId = "";

    if (studentGR) {
        studentSysId = studentGR.getUniqueValue();
        data.student.id = studentGR.getValue("student_id") || "STU_TEST_001";
        data.student.name = studentGR.getValue("student_name") || "Student";
        data.student.email = studentGR.getValue("email") || "";
        data.student.batch = studentGR.getValue("batch") || "";
        data.student.branch = studentGR.getValue("branch") || "";
        data.student.initials = getInitials(data.student.name);
    }

    /*
     * ============================================================
     * POST ACTION HANDLERS (Dismiss, Ignore Opportunity, Clear All)
     * ============================================================
     */
    if (input && input.action && studentSysId) {
        if (input.action === 'dismiss_notification' && input.sys_id) {
            var notifGR = new GlideRecord('x_snc_campus360_student_notification');
            if (notifGR.get(input.sys_id)) {
                notifGR.setValue('status', 'dismissed');
                notifGR.setValue('action_taken', 'true');
                notifGR.update();
            }
        }
        else if (input.action === 'ignore_opportunity' && input.opp_id) {
            var notifGR = new GlideRecord('x_snc_campus360_student_notification');
            notifGR.addQuery('student', studentSysId);
            notifGR.addQuery('opportunity', input.opp_id);
            notifGR.query();
            if (notifGR.next()) {
                notifGR.setValue('status', 'ignored');
                notifGR.setValue('action_taken', 'true');
                notifGR.update();
            } else {
                notifGR.initialize();
                notifGR.setValue('student', studentSysId);
                notifGR.setValue('opportunity', input.opp_id);
                notifGR.setValue('notification_type', 'opportunity_deadline');
                notifGR.setValue('message', 'Ignored placement opportunity reminder');
                notifGR.setValue('status', 'ignored');
                notifGR.setValue('action_taken', 'true');
                notifGR.insert();
            }
        }
        else if (input.action === 'clear_all_notifications') {
            var notifGR = new GlideRecord('x_snc_campus360_student_notification');
            notifGR.addQuery('student', studentSysId);
            notifGR.query();
            while (notifGR.next()) {
                if (notifGR.getValue('status') !== 'ignored') {
                    notifGR.setValue('status', 'dismissed');
                    notifGR.update();
                }
            }
        }
    }

    /*
     * ============================================================
     * PLACEMENT INTELLIGENCE
     * ============================================================
     */
    if (studentSysId) {
        var intelligenceGR = new GlideRecord("x_snc_campus360_placement_intelligence");
        intelligenceGR.addQuery("student", studentSysId);
        intelligenceGR.orderByDesc("last_updated");
        intelligenceGR.setLimit(1);
        intelligenceGR.query();

        if (intelligenceGR.next()) {
            data.readiness.score = parseInt(intelligenceGR.getValue("readiness_score"), 10) || 0;
            data.readiness.risk = intelligenceGR.getDisplayValue("risk_level") || "Low";
            data.readiness.skillGap = intelligenceGR.getDisplayValue("primary_skill_gap") || "No Significant Gap";
            data.readiness.participation = parseInt(intelligenceGR.getValue("participation_score"), 10) || 0;
            data.readiness.missedOpportunities = parseInt(intelligenceGR.getValue("missed_opportunities"), 10) || 0;
            data.readiness.recommendation = intelligenceGR.getValue("recommended_action") || "";
        }
    }

    /*
     * ============================================================
     * APPLICATION & INTERVIEW COUNTS
     * ============================================================
     */
    var appliedOppSysIds = [];
    if (studentSysId) {
        var applicationGR = new GlideRecord("x_snc_campus360_student_application");
        if (applicationGR.isValid()) {
            applicationGR.addQuery("student", studentSysId);
            applicationGR.query();
            data.counts.applications = applicationGR.getRowCount();

            while (applicationGR.next()) {
                var oppId = applicationGR.getValue("opportunity");
                if (oppId) appliedOppSysIds.push(oppId);
            }
        }

        var interviewGR = new GlideRecord("x_snc_campus360_mock_interview");
        if (interviewGR.isValid()) {
            interviewGR.addQuery("student", studentSysId);
            interviewGR.query();
            data.counts.interviews = interviewGR.getRowCount();
        }

        var interventionGR = new GlideRecord("x_snc_campus360_placement_intervention");
        interventionGR.addQuery("student", studentSysId);
        interventionGR.orderByDesc("sys_created_on");
        interventionGR.query();
        data.counts.interventions = interventionGR.getRowCount();

        if (interventionGR.next()) {
            data.intervention.exists = true;
            data.intervention.type = interventionGR.getDisplayValue("intervention_type") || "";
            data.intervention.status = interventionGR.getDisplayValue("status") || "";
            data.intervention.reason = interventionGR.getValue("reason") || "";
            data.intervention.beforeScore = parseInt(interventionGR.getValue("before_score"), 10) || 0;
            data.intervention.afterScore = parseInt(interventionGR.getValue("after_score"), 10) || 0;
            data.intervention.effectiveness = parseInt(interventionGR.getValue("effectiveness_score"), 10) || 0;
            data.intervention.training = interventionGR.getDisplayValue("training") || "";
        }
    }

    /*
     * ============================================================
     * COMPREHENSIVE NOTIFICATION ENGINE FOR STUDENT
     * 1. Check Placement Opportunity Deadlines (Unapplied)
     * 2. Query Student Notification Table (Events & Assessments)
     * ============================================================
     */
    if (studentSysId) {
        var ignoredOppMap = {};
        var existingNotifMap = {};

        // Query existing student notification table entries
        var notifGR = new GlideRecord("x_snc_campus360_student_notification");
        notifGR.addQuery("student", studentSysId);
        notifGR.query();

        while (notifGR.next()) {
            var sysId = notifGR.getUniqueValue();
            var oppRef = notifGR.getValue("opportunity");
            var statusVal = notifGR.getValue("status") || "pending";
            var typeVal = notifGR.getValue("notification_type") || "general";
            var msgVal = notifGR.getValue("message") || "";
            var sentDate = notifGR.getValue("sent_date") || notifGR.getValue("sys_created_on");

            if (oppRef && (statusVal === "ignored" || statusVal === "dismissed")) {
                ignoredOppMap[oppRef] = true;
            }

            if (statusVal !== "ignored" && statusVal !== "dismissed") {
                data.notifications.push({
                    sys_id: sysId,
                    type: typeVal,
                    message: msgVal,
                    date: sentDate,
                    status: statusVal,
                    opportunity_id: oppRef,
                    is_deadline: (typeVal === "opportunity_deadline")
                });
                if (oppRef) existingNotifMap[oppRef] = true;
            }
        }

        // Check Placement Opportunities with deadlines where student HAS NOT APPLIED
        var oppGR = new GlideRecord("x_snc_campus360_placement_opportunity");
        oppGR.addNotNullQuery("deadline");
        oppGR.orderByDesc("deadline");
        oppGR.query();

        while (oppGR.next()) {
            var oppSysId = oppGR.getUniqueValue();
            var companyName = oppGR.getDisplayValue("company") || "Partner Company";
            var roleTitle = oppGR.getValue("job_role") || oppGR.getValue("title") || "Placement Drive";
            var deadlineStr = oppGR.getDisplayValue("deadline") || oppGR.getValue("deadline");

            // Skip if student ALREADY APPLIED or IGNORED/DISMISSED
            if (appliedOppSysIds.indexOf(oppSysId) !== -1) continue;
            if (ignoredOppMap[oppSysId]) continue;
            if (existingNotifMap[oppSysId]) continue;

            // Add dynamic unapplied opportunity deadline reminder
            data.notifications.push({
                sys_id: "dyn_opp_" + oppSysId,
                type: "opportunity_deadline",
                message: "Deadline Reminder: You have not applied for " + roleTitle + " at " + companyName + ". Deadline: " + deadlineStr,
                date: deadlineStr,
                status: "pending",
                opportunity_id: oppSysId,
                is_deadline: true
            });
        }
    }

    data.unreadCount = data.notifications.length;

    /*
     * Safety & Normalization
     */
    if (!data.student.name) data.student.name = "Student";
    if (!data.student.initials) data.student.initials = getInitials(data.student.name);
    data.readiness.score = Math.max(0, Math.min(100, data.readiness.score));
    data.readiness.participation = Math.max(0, Math.min(100, data.readiness.participation));

})();
